(function() {
    'use strict';

    class WomenLeadershipAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Women in Leadership: Building the Pipeline';
            this.version = '1.1.0';

            this.INTERVENTIONS = [
                { id: 'intA', cost: 180, pei: 8, ocs: 4, tri: 4, rcs: 1, bci: 3 },
                { id: 'intB', cost: 120, pei: 4, ocs: 1, tri: 1, rcs: 1, bci: 1 },
                { id: 'intC', cost: 95, pei: 5, ocs: 3, tri: 3, rcs: 2, bci: 2 },
                { id: 'intD', cost: 380, pei: 2, ocs: 7, tri: 3, rcs: 1, bci: 1 },
                { id: 'intE', cost: 705, pei: 1, ocs: 6, tri: 7, rcs: 8, bci: 2 },
                { id: 'intF', cost: 145, pei: 1, ocs: 2, tri: 1, rcs: 0, bci: 0 }
            ];

            this.BUDGET_CAP = 1500;

            this.R2_SCORES = {
                scopeA1:  { pei: 0, ocs: 2, tri: 2, rcs: 4, bci: 1 },
                scopeA2:  { pei: 3, ocs: 5, tri: 4, rcs: 7, bci: 3 },
                scopeA3:  { pei: 5, ocs: 7, tri: 5, rcs: 9, bci: 4 },
                discB1:   { pei: 0, ocs:-1, tri: 0, rcs: 2, bci: 0 },
                discB2:   { pei: 1, ocs: 4, tri: 3, rcs: 5, bci: 3 },
                discB3:   { pei: 1, ocs: 2, tri: 1, rcs: 4, bci: 4 },
                commC1:   { pei: 0, ocs:-2, tri:-1, rcs: 1, bci: 0 },
                commC2:   { pei: 2, ocs: 3, tri: 2, rcs: 3, bci: 2 },
                commC3:   { pei: 1, ocs: 4, tri: 3, rcs: 2, bci: 1 }
            };

            this.R3_SCORES = {
                succA1:  { pei:-1, ocs: 0, tri:-1, rcs: 0, bci: 1 },
                succA2:  { pei: 5, ocs: 3, tri: 3, rcs: 0, bci: 4 },
                succA3:  { pei: 1, ocs: 1, tri: 0, rcs: 0, bci:-1 },
                succA4:  { pei: 3, ocs: 2, tri: 1, rcs: 0, bci: 2 },
                sponsB1: { pei: 1, ocs: 2, tri: 1, rcs: 0, bci: 0 },
                sponsB2: { pei: 3, ocs: 3, tri: 3, rcs: 0, bci: 2 },
                sponsB3: { pei: 5, ocs: 4, tri: 4, rcs: 0, bci: 3 },
                procC1:  { pei: 2, ocs: 1, tri: 1, rcs: 1, bci: 1 },
                procC2:  { pei: 3, ocs: 2, tri: 2, rcs: 2, bci: 1 },
                procC3:  { pei: 2, ocs: 3, tri: 2, rcs: 0, bci: 1 },
                procC4:  { pei: 5, ocs: 4, tri: 3, rcs: 2, bci: 2 }
            };

            this.R4_SCORES = {
                parD1a:  { pei: 2, ocs: 5, tri: 5, rcs: 3, bci: 2 },
                parD1b:  { pei: 2, ocs: 4, tri: 4, rcs: 3, bci: 2 },
                parD1c:  { pei: 0, ocs: 2, tri: 2, rcs: 1, bci: 0 },
                flexD2a: { pei: 2, ocs: 3, tri: 3, rcs: 2, bci: 1 },
                flexD2b: { pei: 1, ocs: 2, tri: 2, rcs: 1, bci: 1 },
                flexD2c: { pei: 1, ocs: 4, tri: 3, rcs: 1, bci: 1 },
                flexD2d: { pei: 3, ocs: 5, tri: 4, rcs: 2, bci: 2 },
                compD3a: { pei: 1, ocs: 3, tri: 2, rcs: 5, bci: 1 },
                compD3b: { pei: 0, ocs: 1, tri: 1, rcs: 3, bci: 0 },
                compD3c: { pei: 0, ocs:-1, tri:-1, rcs: 1, bci: 0 },
                promD4a: { pei: 2, ocs: 2, tri: 2, rcs: 2, bci: 1 },
                promD4b: { pei: 3, ocs: 2, tri: 3, rcs: 3, bci: 1 },
                promD4c: { pei: 2, ocs: 3, tri: 3, rcs: 2, bci: 1 }
            };

            this.R5_SCORES = {
                resA1:  { pei: 0, ocs: 2, tri: 1, rcs: 0, bci: 0 },
                resA2:  { pei: 1, ocs: 1, tri: 1, rcs: 0, bci: 1 },
                resA3:  { pei: 0, ocs: 3, tri: 1, rcs: 0, bci: 0 },
                resA4:  { pei: 1, ocs: 2, tri: 1, rcs: 1, bci: 1 },
                resA5:  { pei: 2, ocs: 3, tri: 2, rcs: 1, bci: 2 },
                measB1: { pei: 1, ocs: 0, tri: 0, rcs: 1, bci: 0 },
                measB2: { pei: 2, ocs: 2, tri: 2, rcs: 2, bci: 2 },
                measB3: { pei: 3, ocs: 3, tri: 2, rcs: 3, bci: 3 },
                compC1: { pei: 1, ocs: 1, tri: 1, rcs: 0, bci: 1 },
                compC2: { pei: 2, ocs: 2, tri: 1, rcs: 2, bci: 3 },
                compC3: { pei: 1, ocs: 3, tri: 2, rcs: 1, bci: 2 }
            };

            this.R6_SCORES = {
                frameA1: { pei: 0, ocs: 0, tri: 0, rcs: 3, bci: 1 },
                frameA2: { pei: 1, ocs: 2, tri: 2, rcs: 0, bci: 2 },
                frameA3: { pei: 0, ocs: 0, tri: 0, rcs: 0, bci: 3 },
                frameA4: { pei: 2, ocs: 2, tri: 2, rcs: 2, bci: 4 },
                nextB1:  { pei: 1, ocs: 1, tri: 1, rcs: 1, bci: 0 },
                nextB2:  { pei: 3, ocs: 2, tri: 2, rcs: 2, bci: 3 },
                nextB3:  { pei: 2, ocs: 3, tri: 3, rcs: 2, bci: 2 },
                nextB4:  { pei: 2, ocs: 2, tri: 1, rcs: 3, bci: 4 }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    pei: 30,
                    ocs: 54,
                    tri: 40,
                    rcs: 50,
                    bci: 45,
                    peiHistory: [],
                    ocsHistory: [],
                    triHistory: [],
                    rcsHistory: [],
                    bciHistory: [],
                    overallHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
        }

        _getBriefingHTML(roundIndex) {
            var briefs = [
                '<h3>Round 1 — The Diagnosis: Understanding Why the Pipeline Leaks</h3><p>You are <b>Valentina Rodriguez</b>, the new Chief People Officer of <b>Meridian Financial Group</b>, a 4,000-employee LATAM financial services company. Your pipeline audit reveals critical findings:</p><div class="wlp-data-highlight"><b>Promotion Gap:</b> Women promoted at 12.3% vs. men at 17.8% — despite women averaging higher performance ratings (3.31 vs. 3.19).<br><b>Hiring Gap:</b> Salary offers to women are 8.3% lower than to men in the same role.<br><b>Culture Gap:</b> Psychological safety scores are 12 points lower for women.<br><b>Network Gap:</b> Women are 2.3 hops further from senior leadership nodes.</div><p>You have <b>$1,500K</b> to allocate across six interventions. Select which to fund. You cannot fund all of them — prioritize based on root cause analysis.</p>',

                '<h3>Round 2 — Pay Equity: When the Numbers Tell an Uncomfortable Story</h3><p>Month 8. A comprehensive pay equity analysis reveals:</p><div class="wlp-data-highlight"><b>Raw Gap:</b> Women earn 31% less than men across all markets.<br><b>Adjusted Gap (same role/level/tenure):</b> Colombia 9.2%, Peru 11.7%, Chile 7.4%.<br><b>Structural Gap:</b> Occupational segregation accounts for ~20 points — women concentrated in lower-paying functions.<br><b>Cohort Analysis:</b> After 8 years in matched entry roles, the compensation gap reaches 47%.</div><p>The CFO wants phased remediation. The General Counsel warns of legal exposure. A union in Colombia may leak the report. Make three decisions on scope, disclosure, and manager communication.</p>',

                '<h3>Round 3 — Sponsorship and Succession: Building the Next Generation</h3><p>Month 14. The Director of Commercial Banking Colombia retires in 7 months. Three candidates:</p><div class="wlp-data-highlight"><b>Fernando Castillo (M, 41):</b> 12 years at Meridian. Strong client relationships ($145M revenue). Exceeds expectations 4/5 years. No digital or international experience.<br><b>Claudia Mendoza (F, 38):</b> 10 years total. Led digital onboarding (+23% SME acquisition). Exceeds expectations 5/5 years. International experience. No senior sponsor.<br><b>Andres Villareal (M, 44):</b> 16 years. Meets expectations consistently. One below rating. Strong sponsor network from retiring executives.</div><p>Additionally, only 9 of 34 senior mentors have actively sponsored a woman in 24 months. Design the succession recommendation, sponsorship program, and succession process.</p>',

                '<h3>Round 4 — Flexible Work and the Culture of Presence</h3><p>Month 20. New regulatory requirements demand flexible work utilization data disaggregated by gender. Your internal data reveals:</p><div class="wlp-data-highlight"><b>Telework:</b> 31% of women use it vs. 23% of men.<br><b>Paternity leave:</b> Men take only 4.2 of 10 entitled days.<br><b>Reduced hours:</b> Zero employees at Director+ have used it in 5 years.<br><b>Promotion penalty:</b> Flexible work users are 28% less likely to be promoted (33% for women, 19% for men).<br><b>Complaints:</b> 12 complaints about managers linking flexibility to career commitment. 2 are legally actionable.</div><p>Redesign parental leave, flexibility culture, complaint response, and the promotion-flexibility link.</p>',

                '<h3>Round 5 — Measurement and Resistance: Sustaining the Change</h3><p>Month 28. Progress is real but uneven, and resistance is building:</p><div class="wlp-data-highlight"><b>Progress:</b> Women at Manager: 29% to 34%. Senior Manager: 21% to 24%. Pay gap: 9.2% to 3.1%. Attrition gap: 7pp to 1pp.<br><b>Resistance:</b> 8 senior male commercial bankers sent an anonymous letter claiming "standards are being compromised by forced diversity quotas" and "qualified male candidates are being passed over."<br><b>Competition:</b> Two competitors outperform Meridian on gender equity and are attracting better talent.</div><p>Respond to the resistance, design the permanent measurement framework, and address the competitive threat.</p>',

                '<h3>Round 6 — Synthesis: Presenting the Business Case to the Board</h3><p>Month 36. Present your 3-year results to a mixed board: family members (financial focus), an institutional investor (ESG focus), a retired judge (legal focus), and the CEO.</p><div class="wlp-data-highlight"><b>3-Year Results:</b> Women at Manager: 29% to 34%. Adjusted pay gap: 9.2% to 3.1%. High-performer attrition gap: 7pp to 1pp. Culture score: 54 to 65.<br><b>Revenue correlation:</b> The 3 most equity-advanced units outperformed targets by 8.3%. The 3 least advanced underperformed by 4.1%.<br><b>Employee NPS (Women):</b> 28 to 41.</div><p>Frame the business case and recommend the next-phase strategy for Years 3-5.</p>'
            ];
            return briefs[roundIndex] || '';
        }

        _getDecisionsHTML(roundIndex) {
            var panels = [];

            if (roundIndex === 0) {
                panels.push('<h4 data-i18n="r1_heading">Year One Intervention Portfolio</h4>');
                var items = [
                    ['intA', 180, 'A: Structured Promotion Process Redesign — Blind review, diverse calibration panels, documented decisions'],
                    ['intB', 120, 'B: Job Description Audit — Remove masculine-coded language from 800+ descriptions'],
                    ['intC', 95, 'C: Hiring Panel Composition — Gender-balanced panels for all Manager+ roles'],
                    ['intD', 380, 'D: Comprehensive Bias Awareness Training — 6-hour experiential program for 450 managers'],
                    ['intE', 705, 'E: Salary Benchmarking Remediation — Correct 8.3% hiring gap + retroactive audit'],
                    ['intF', 145, 'F: Structured Mentoring Program — 6-month program pairing 80 high-potential women with VP mentors']
                ];
                for (var i = 0; i < items.length; i++) {
                    panels.push('<div class="wlp-checkbox-group"><input type="checkbox" id="' + items[i][0] + '" value="' + items[i][1] + '"><label for="' + items[i][0] + '">' + items[i][2] + '</label><span class="wlp-cost">$' + items[i][1] + 'K</span></div>');
                }
            }

            if (roundIndex === 1) {
                panels.push('<h4 data-i18n="r2_heading">Pay Equity Decisions</h4>');
                panels.push('<label data-i18n="r2_scope">Decision A — Remediation Scope</label>');
                panels.push('<select id="r2scope"><option value="">-- Select --</option><option value="scopeA1">A1: Remediate adjusted gap only, phase over 3 years ($3.2M)</option><option value="scopeA2">A2: Remediate adjusted gap immediately + 5-year structural plan ($5.8M+)</option><option value="scopeA3">A3: Full remediation of both gaps with annual public reporting ($5.8M + $12M)</option></select>');
                panels.push('<label data-i18n="r2_disc">Decision B — Disclosure Approach</label>');
                panels.push('<select id="r2disc"><option value="">-- Select --</option><option value="discB1">B1: Disclose only legally required data (Brazil raw figures)</option><option value="discB2">B2: Proactive full disclosure — annual Gender Pay Equity Report on website</option><option value="discB3">B3: Present findings at investor day briefing before public disclosure</option></select>');
                panels.push('<label data-i18n="r2_comm">Decision C — Manager Communication</label>');
                panels.push('<select id="r2comm"><option value="">-- Select --</option><option value="commC1">C1: Silent corrections — no systemic explanation to managers</option><option value="commC2">C2: Full transparency — brief all managers, share team data, hold accountable</option><option value="commC3">C3: Hold harmless for past, build equity into future evaluations</option></select>');
            }

            if (roundIndex === 2) {
                panels.push('<h4 data-i18n="r3_heading">Sponsorship and Succession Decisions</h4>');
                panels.push('<label data-i18n="r3_succ">Decision A — Succession Recommendation</label>');
                panels.push('<select id="r3succ"><option value="">-- Select --</option><option value="succA1">A1: Recommend Fernando (safest choice, strong client relationships)</option><option value="succA2">A2: Recommend Claudia (strongest performance, digital expertise, strategic fit)</option><option value="succA3">A3: Delay decision — 6-month development for Claudia, then revisit</option><option value="succA4">A4: Fernando as Director with Claudia as formal deputy and 18-month successor</option></select>');
                panels.push('<label data-i18n="r3_spons">Decision B — Sponsorship Program Design</label>');
                panels.push('<select id="r3spons"><option value="">-- Select --</option><option value="sponsB1">B1: Basic — Monthly meetings, career advice focus, same-function matching</option><option value="sponsB2">B2: Moderate — Cross-functional matching, one high-visibility project nomination required</option><option value="sponsB3">B3: High accountability — Cross-functional, ExCo presentation required, succession inclusion</option></select>');
                panels.push('<label data-i18n="r3_proc">Decision C — Succession Planning Process</label>');
                panels.push('<select id="r3proc"><option value="">-- Select --</option><option value="procC1">C1: Require at least one woman in every top-3 succession slate</option><option value="procC2">C2: Require slates to reflect gender composition of the level below</option><option value="procC3">C3: Require "Who have we missed?" exercise before finalizing slates</option><option value="procC4">C4: Implement all three requirements together</option></select>');
            }

            if (roundIndex === 3) {
                panels.push('<h4 data-i18n="r4_heading">Flexible Work Redesign</h4>');
                panels.push('<label data-i18n="r4_par">Dimension 1 — Parental Leave Redesign</label>');
                panels.push('<select id="r4par"><option value="">-- Select --</option><option value="parD1a">D1a: Extend paternity to 12 weeks, non-transferable, CEO communication</option><option value="parD1b">D1b: Shared pool of 26 weeks, minimum 8 weeks reserved per parent</option><option value="parD1c">D1c: Maintain current + add return-to-work transition for fathers</option></select>');
                panels.push('<label data-i18n="r4_flex">Dimension 2 — Flexibility Culture</label>');
                panels.push('<select id="r4flex"><option value="">-- Select --</option><option value="flexD2a">D2a: Location-neutral performance evaluation policy</option><option value="flexD2b">D2b: Results-only work environment (ROWE) pilot in 2 divisions</option><option value="flexD2c">D2c: Require all managers to model flexible work use publicly</option><option value="flexD2d">D2d: Combine location-neutral evaluation + leader modeling</option></select>');
                panels.push('<label data-i18n="r4_comp">Dimension 3 — Handling Complaints</label>');
                panels.push('<select id="r4comp"><option value="">-- Select --</option><option value="compD3a">D3a: Investigate all 12, formal warnings for 2 actionable cases, report to CEO</option><option value="compD3b">D3b: Investigate 2 legally actionable only, team training for rest</option><option value="compD3c">D3c: Generic management communication, no individual investigations</option></select>');
                panels.push('<label data-i18n="r4_prom">Dimension 4 — Promotion-Flexibility Correlation</label>');
                panels.push('<select id="r4prom"><option value="">-- Select --</option><option value="promD4a">D4a: Calibration committees review flex-work data and flag biased decisions</option><option value="promD4b">D4b: Annual promotion equity audit — automatic review if flex users promoted less</option><option value="promD4c">D4c: Remove manager discretion — automatic qualification based on performance</option></select>');
            }

            if (roundIndex === 4) {
                panels.push('<h4 data-i18n="r5_heading">Measurement and Resistance</h4>');
                panels.push('<label data-i18n="r5_res">Challenge A — Responding to Resistance</label>');
                panels.push('<select id="r5res"><option value="">-- Select --</option><option value="resA1">A1: Meet individually with the 8 authors — listen, address facts</option><option value="resA2">A2: CEO meets the coalition collectively — reaffirm commitment</option><option value="resA3">A3: Anonymous survey of all 450+ managers to gauge breadth of resistance</option><option value="resA4">A4: Independent analysis of promotion decisions to verify or refute claims</option><option value="resA5">A5: Combine CEO reaffirmation + evidence-based promotion analysis</option></select>');
                panels.push('<label data-i18n="r5_meas">Challenge B — Measurement Framework</label>');
                panels.push('<select id="r5meas"><option value="">-- Select --</option><option value="measB1">B1: Track representation percentages only (lagging indicators)</option><option value="measB2">B2: Leading + lagging indicators with relative improvement targets</option><option value="measB3">B3: Intersectional data, leading + lagging, executive compensation linkage</option></select>');
                panels.push('<label data-i18n="r5_comp">Challenge C — Competitor Response</label>');
                panels.push('<select id="r5comp"><option value="">-- Select --</option><option value="compC1">C1: Accelerate current program with more aggressive targets</option><option value="compC2">C2: Joint industry initiative — collective gender equity standard</option><option value="compC3">C3: Publish authentic equity journey including setbacks</option></select>');
            }

            if (roundIndex === 5) {
                panels.push('<h4 data-i18n="r6_heading">Board Presentation Strategy</h4>');
                panels.push('<label data-i18n="r6_frame">Decision A — Business Case Framing</label>');
                panels.push('<select id="r6frame"><option value="">-- Select --</option><option value="frameA1">A1: Lead with compliance and legal risk reduction</option><option value="frameA2">A2: Lead with talent economics — reduced attrition, improved NPS</option><option value="frameA3">A3: Lead with revenue correlation — 8.3% outperformance data</option><option value="frameA4">A4: Integrated framework — risk, talent, and performance dimensions together</option></select>');
                panels.push('<label data-i18n="r6_next">Decision B — Next-Phase Commitment (Years 3-5)</label>');
