        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 5);

            var briefEl = document.getElementById('briefingPanel');
            if (briefEl) briefEl.innerHTML = this._getBriefingHTML(idx);

            var decEl = document.getElementById('decisionsPanel');
            if (decEl) decEl.innerHTML = this._getDecisionsHTML(idx);

            var budgetBar = document.getElementById('budgetBar');
            if (budgetBar) budgetBar.style.display = (idx === 0) ? 'block' : 'none';

            if (idx === 0) this._setupBudgetListeners();
        }

        _setupBudgetListeners() {
            var self = this;
            var caps = self.BUDGET_CAP;
            var ints = self.INTERVENTIONS;
            for (var i = 0; i < ints.length; i++) {
                var cb = document.getElementById(ints[i].id);
                if (cb) {
                    cb.addEventListener('change', function() {
                        var total = 0;
                        for (var j = 0; j < ints.length; j++) {
                            var el = document.getElementById(ints[j].id);
                            if (el && el.checked) total += ints[j].cost;
                        }
                        var usedEl = document.getElementById('budgetUsed');
                        if (usedEl) {
                            usedEl.textContent = '$' + total + 'K';
                            usedEl.className = total > caps ? 'wlp-over-budget' : '';
                        }
                    });
                }
            }
        }

        validateDecisions(decisions) {
            var round = (window.mySimulation.state.currentPeriod || 1);

            if (round === 1) {
                var funded = [];
                var totalCost = 0;
                for (var i = 0; i < this.INTERVENTIONS.length; i++) {
                    var cb = document.getElementById(this.INTERVENTIONS[i].id);
                    if (cb && cb.checked) {
                        funded.push(this.INTERVENTIONS[i].id);
                        totalCost += this.INTERVENTIONS[i].cost;
                    }
                }
                if (funded.length === 0) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_no_selection'), 'warning');
                    return false;
                }
                if (totalCost > this.BUDGET_CAP) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_over_budget'), 'warning');
                    return false;
                }
                decisions.funded = funded;
                decisions.totalCost = totalCost;
                return true;
            }

            if (round === 2) {
                var s = document.getElementById('r2scope');
                var d = document.getElementById('r2disc');
                var c = document.getElementById('r2comm');
                if (!s || !s.value || !d || !d.value || !c || !c.value) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_incomplete'), 'warning');
                    return false;
                }
                decisions.r2scope = s.value;
                decisions.r2disc = d.value;
                decisions.r2comm = c.value;
                return true;
            }

            if (round === 3) {
                var su = document.getElementById('r3succ');
