                return true;
            }

            if (round === 5) {
                var re = document.getElementById('r5res');
                var me = document.getElementById('r5meas');
                var cm = document.getElementById('r5comp');
                if (!re || !re.value || !me || !me.value || !cm || !cm.value) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_incomplete'), 'warning');
                    return false;
