        _applyScores(ds, scoreObj) {
            ds.pei = Math.min(100, Math.max(0, ds.pei + (scoreObj.pei || 0)));
            ds.ocs = Math.min(100, Math.max(0, ds.ocs + (scoreObj.ocs || 0)));
            ds.tri = Math.min(100, Math.max(0, ds.tri + (scoreObj.tri || 0)));
            ds.rcs = Math.min(100, Math.max(0, ds.rcs + (scoreObj.rcs || 0)));
            ds.bci = Math.min(100, Math.max(0, ds.bci + (scoreObj.bci || 0)));
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var peiDelta = 0, ocsDelta = 0, triDelta = 0, rcsDelta = 0, bciDelta = 0;

            if (round === 1) {
                var funded = d.funded || [];
                for (var i = 0; i < this.INTERVENTIONS.length; i++) {
                    if (funded.indexOf(this.INTERVENTIONS[i].id) !== -1) {
                        peiDelta += this.INTERVENTIONS[i].pei;
                        ocsDelta += this.INTERVENTIONS[i].ocs;
                        triDelta += this.INTERVENTIONS[i].tri;
                        rcsDelta += this.INTERVENTIONS[i].rcs;
                        bciDelta += this.INTERVENTIONS[i].bci;
                    }
                }
            }

            if (round === 2) {
                var keys2 = [d.r2scope, d.r2disc, d.r2comm];
                for (var k = 0; k < keys2.length; k++) {
                    var sc = this.R2_SCORES[keys2[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            if (round === 3) {
                var keys3 = [d.r3succ, d.r3spons, d.r3proc];
                for (var k = 0; k < keys3.length; k++) {
                    var sc = this.R3_SCORES[keys3[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            if (round === 4) {
                var keys4 = [d.r4par, d.r4flex, d.r4comp, d.r4prom];
                for (var k = 0; k < keys4.length; k++) {
                    var sc = this.R4_SCORES[keys4[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            if (round === 5) {
                var keys5 = [d.r5res, d.r5meas, d.r5comp];
                for (var k = 0; k < keys5.length; k++) {
                    var sc = this.R5_SCORES[keys5[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            if (round === 6) {
                var keys6 = [d.r6frame, d.r6next];
                for (var k = 0; k < keys6.length; k++) {
                    var sc = this.R6_SCORES[keys6[k]];
                    if (sc) { peiDelta += sc.pei; ocsDelta += sc.ocs; triDelta += sc.tri; rcsDelta += sc.rcs; bciDelta += sc.bci; }
                }
            }

            ds.pei = Math.min(100, Math.max(0, ds.pei + peiDelta));
            ds.ocs = Math.min(100, Math.max(0, ds.ocs + ocsDelta));
            ds.tri = Math.min(100, Math.max(0, ds.tri + triDelta));
            ds.rcs = Math.min(100, Math.max(0, ds.rcs + rcsDelta));
            ds.bci = Math.min(100, Math.max(0, ds.bci + bciDelta));

            var overall = Math.round(ds.pei * 0.25 + ds.ocs * 0.20 + ds.tri * 0.20 + ds.rcs * 0.20 + ds.bci * 0.15);

            ds.peiHistory.push(ds.pei);
            ds.ocsHistory.push(ds.ocs);
            ds.triHistory.push(ds.tri);
            ds.rcsHistory.push(ds.rcs);
            ds.bciHistory.push(ds.bci);
            ds.overallHistory.push(overall);

            var self = this;
            var period = round;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: round,
                peiDelta: peiDelta,
                ocsDelta: ocsDelta,
                triDelta: triDelta,
                rcsDelta: rcsDelta,
                bciDelta: bciDelta,
                pei: ds.pei,
                ocs: ds.ocs,
                tri: ds.tri,
                rcs: ds.rcs,
                bci: ds.bci,
                overall: overall
            };
        }

