        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var overall = r.overall || 0;

            var performance = 'Developing';
            if (overall >= 75) performance = 'Excellent';
            else if (overall >= 60) performance = 'Proficient';
            else if (overall >= 45) performance = 'Competent';

            var insights = [];
            if (r.pei >= 55) insights.push('Strong pipeline equity gains — structural interventions are working.');
            if (r.pei < 40) insights.push('Pipeline equity remains low. Structural promotion and hiring changes have the strongest evidence base.');
            if (r.ocs >= 70) insights.push('Organizational culture transformation is well underway.');
            if (r.ocs < 55) insights.push('Culture score needs attention. Consider leader modeling and transparency.');
            if (r.rcs >= 75) insights.push('Regulatory compliance is strong across all markets.');
            if (r.bci >= 65) insights.push('The business case for equity is well-established with data.');
            if (r.tri < 50) insights.push('Retention of high-performing women still needs improvement.');

            return {
                overall: overall,
                pei: r.pei,
                ocs: r.ocs,
                tri: r.tri,
                rcs: r.rcs,
                bci: r.bci,
                performance: performance,
                insights: insights
            };
        }

